local jm,km={},{}
for lm,nm in pairs(bb.helperDealt or{})do
if nm.owner then
jm[nm.owner]=(jm[nm.owner]or 0)+(tonumber(nm.v)or 0)
end
end
for om,qm in ipairs(bb.mine or{})do
local rm=qm:FindFirstChild(CJe[2324])
local um=rm and rm:FindFirstChild(CJe[2645])
if um then
km[um.Value]=(km[um.Value]or 0)+1
end
end
local vm,wm,xm,ym
for zm,Am in ipairs(bb.mine or{})do
local Bm=Am:FindFirstChild(CJe[2324])
local Cm=Bm and Bm:FindFirstChild(CJe[2645])
local Dm=Cm and Cm.Value
if Dm and Dm~=am.id and not V.isFarm(Dm)and not V.allyBuff(Dm)then
local Em=Bm:FindFirstChild(CJe[2646])
local Fm=type(bb.ownDealt)==CJe[2252]and bb.ownDealt[Am]and tonumber(bb.ownDealt[Am].v)or 0
local Gm=math.max(Em and tonumber(Em.Value)or 0,Fm)+(jm[Dm]or 0)/math.max(1,km[Dm]or 1)
