local Im=tonumber(Hm and Hm[0]and Hm[0].cost)or math.huge
local Jm=Bm:FindFirstChild(CJe[2355])
local Km=Jm and tonumber(Jm.Value)or 0
if not vm or Gm<wm or(Gm==wm and Im<xm)then
vm,wm,xm,ym=Am,Gm,Im,Km
end
end
end
if not vm then
F.log(1,CJe[2641],string.format(CJe[2647],V.name(am.id)))
