if Mm and Nm then
table.insert(bb.actions,CJe[2648]..Lm..CJe[2649])
F.log(1,CJe[2641],string.format(CJe[2650],V.name(am.id),Lm,ym or 0,U.fmt(wm or 0),V.name(am.id)))
