if Vm.id==Pm and Tm>=Vm.t-0.5 and Tm<=Vm.t+10 then
Rm=Rm+1
break
end
end
end
return Rm
end
function pb.watchIds()
local Wm,Xm={},0
if P.trial and P.trial.study and bb.trialId then
Wm[bb.trialId]=true
Xm=Xm+1
end
if O.pasWatch~=false then
for Ym,Zm in ipairs(bb.team or{})do
if not Wm[Zm.id]then
local _m,an=pcall(pb.guess,Zm.id)
for bn,cn in ipairs(_m and type(an)==CJe[2252]and an or{})do
if cn.playable and not cn.hand and pb.sure(Zm.id,cn)~=CJe[2630]then
Wm[Zm.id]=true
Xm=Xm+1
