local ao=bb.pasExp
if type(ao)==CJe[2252]and ao.kind==CJe[2451]and not ao.otherDone and not ao.freed and bb.reinc and(bb.reinc.sold or 0)>0 and U.now()-(tonumber(bb.reinc.soldAt)or 0)>20 then
local bo,co=pcall(pb.freeSlot,ao)
if not bo then
ao.freed=true
F.log(1,CJe[2261],CJe[2660]..tostring(co))
end
end
local eo={}
for fo,ho in pairs(gn.copies)do
if not ho.gone and gn.ids[ho.id]and ho.pos and ho.range then
table.insert(eo,ho)
end
end
local io,jo={},0
for ko,mo in ipairs(bb.enemies or{})do
local oo=mo.m
if oo and mo.pos then
io[oo]=true
local po=false
local qo=U.flat(mo.pos)
for ro,so in ipairs(eo)do
if(qo-U.flat(so.pos)).Magnitude<=so.range+3 then
po=true
break
end
end
local uo=gn.foe[oo]
if po or uo then
local vo=oo:FindFirstChildOfClass(CJe[2661])
local wo=math.max(1,(vo and vo.MaxHealth)or mo.hp or 1)
if not uo then
uo={hp=mo.hp,on={},met={},speed0=vo and vo.WalkSpeed or nil,boss=mo.boss or nil}
gn.foe[oo]=uo
gn.nearN=gn.nearN+1
end
jo=jo+1
if jo<=pb.ENEMY_MAX then
local xo=oo:FindFirstChild(CJe[2324])
local yo={}
for zo,Ao in ipairs(xo and xo:GetChildren()or{})do
if Ao.Name:sub(1,8)==CJe[2662]and Ao:IsA(CJe[2656])and tonumber(Ao.Value)then
yo[Ao.Name]=tonumber(Ao.Value)/wo
end
end
local Bo=((uo.hp or mo.hp)-mo.hp)/wo
if Bo>=0.08 and#gn.steps<300 then
local Co
for Do,Eo in pairs(uo.met)do
if Eo>0.02 and(yo[Do]or 0)<Eo*0.3 then
Co=Co or{}
Co[Do]=Eo
end
end
table.insert(gn.steps,{t=kn,before=(uo.hp or mo.hp)/wo,drop=Bo,boss=mo.boss or nil,reset=Co})
end
for Fo,Go in pairs(yo)do
local Ho=gn.meters[Fo]or{max=0,n=0}
Ho.max,Ho.n=math.max(Ho.max,Go),Ho.n+1
gn.meters[Fo]=Ho
end
uo.met=yo
local Io=oo:FindFirstChild(CJe[2655])
local Jo={}
for Ko,Lo in ipairs(Io and Io:GetChildren()or{})do
local Mo=(Lo:IsA(CJe[2656])and tonumber(Lo.Value))or 1
if Mo~=0 then
Jo[Lo.Name]=Mo
end
end
for No,Oo in pairs(Jo)do
local Po=gn.foeBuffs[No]
if not Po then
Po={first=kn,last=kn,n=0,foes=0,near=0,boss=0,max=Oo,durs={},sp=0,spN=0,onsets={}}
gn.foeBuffs[No]=Po
end
Po.n,Po.last,Po.max=Po.n+1,kn,math.max(Po.max,Oo)
if po then
Po.near=Po.near+1
end
if uo.boss then
Po.boss=Po.boss+1
end
if not uo.on[No]then
uo.on[No]=kn
Po.foes=Po.foes+1
if#Po.onsets<200 then
table.insert(Po.onsets,kn)
end
end
if vo and(uo.speed0 or 0)>0 then
Po.sp,Po.spN=Po.sp+vo.WalkSpeed/uo.speed0,Po.spN+1
end
end
for Qo,Ro in pairs(uo.on)do
if not Jo[Qo]then
local So=gn.foeBuffs[Qo]
if So and#So.durs<80 then
table.insert(So.durs,kn-Ro)
end
uo.on[Qo]=nil
end
end
end
uo.hp=mo.hp
uo.frac=(mo.hp or 0)/wo
end
end
end
for To,Uo in pairs(gn.foe)do
if not io[To]then
if#gn.deaths<600 and Uo.frac then
table.insert(gn.deaths,{frac=Uo.frac,boss=Uo.boss})
end
gn.foe[To]=nil
end
end
for Vo,Wo in pairs(bb.helperDealt or{})do
if Wo.owner and gn.ids[Wo.owner]then
local Xo=gn.sumOf[Vo]
if not Xo then
local Yo=0
for Zo,_o in pairs(gn.copies)do
