end
return{seen=true,buff=xq,nums={maxSeen=yq.max,steps= #yq.vals,transformTo=Bq},why=string.format(CJe[2683],xq,tostring(yq.max))}
end
if ep.family==CJe[2450]then
local Lq,Mq,Nq={},{},nil
