function pb.learn(Sq)
local Tq={}
for Uq in pairs(Sq.ids or{})do
local Vq,Wq=pcall(pb.guess,Uq)
for Xq,Yq in ipairs(Vq and type(Wq)==CJe[2252]and Wq or{})do
if Yq.playable and not Yq.hand then
local Zq,_q=pcall(pb.evidence,Sq,Uq,Yq)
if Zq and type(_q)==CJe[2252]and _q.seen then
local ar=type(P.pasBook[Uq])==CJe[2252]and P.pasBook[Uq]or{}
local br=type(ar[Yq.pid])==CJe[2252]and ar[Yq.pid]or nil
local cr={}
for dr,er in pairs(Yq.nums or{})do
cr[dr]=er
end
for gr,hr in pairs(_q.nums or{})do
cr[gr]=hr
end
local ir=br~=nil and br.family==Yq.family and(br.buff==nil or _q.buff==nil or br.buff==_q.buff)
ar[Yq.pid]={family=Yq.family,name=Yq.name,nums=cr,buff=_q.buff or(br and br.buff),who=_q.who or Yq.who,trigger=Yq.trigger,keyword=Yq.keyword,sure=(ir and(tonumber(br.runs)or 0)>=1)and CJe[2630]or CJe[2688],runs=(ir and(tonumber(br.runs)or 0)or 0)+1,at=os.time(),why=_q.why}
P.pasBook[Uq]=ar
table.insert(Tq,{id=Uq,g=Yq,e=ar[Yq.pid]})
elseif Zq and type(_q)==CJe[2252]then
table.insert(Tq,{id=Uq,g=Yq,miss=_q.why})
else
table.insert(Tq,{id=Uq,g=Yq,miss=CJe[2689]..tostring(_q)})
end
end
end
end
pb._model={}
return Tq
end
function pb.unexplained(jr,kr)
if not(jr and jr.firstPlaced and jr.firstPlaced[kr])then
return nil
end
local lr={}
for mr,nr in ipairs(jr.learned or{})do
if nr.id==kr and nr.e and nr.e.buff then
lr[nr.e.buff]=true
end
end
local qr={}
for rr,sr in pairs(jr.own)do
if(sr.by[kr]or 0)>0 and not lr[rr]then
table.insert(qr,{w=CJe[2690],b=rr,n=sr.by[kr],max=sr.max})
end
end
for ur,vr in pairs(jr.foeBuffs)do
if vr.near>0 and vr.first>=jr.firstPlaced[kr]-1 and not lr[ur]then
table.insert(qr,{w=CJe[2691],b=ur,n=vr.foes,max=vr.max})
end
end
table.sort(qr,function(wr,xr)
return wr.n>xr.n
end)
local yr={}
for zr=1,math.min(6,#qr)do
yr[zr]=qr[zr]
end
return#yr>0 and yr or nil
end
function pb.finish()
local Ar=bb.pas
if not(Ar and(Ar.n or 0)>0)then
return
end
local Br=pb.learn(Ar)
Ar.learned=Br
local Cr=P.trial and P.trial.study
if Cr and bb.trialId then
P.pasBook[bb.trialId]=type(P.pasBook[bb.trialId])==CJe[2252]and P.pasBook[bb.trialId]or{}
P.pasBook[bb.trialId]._tries=(tonumber(P.pasBook[bb.trialId]._tries)or 0)+1
end
for Dr,Er in ipairs(Br)do
if Er.e then
F.log(1,CJe[2641],string.format(CJe[2692],V.name(Er.id),Er.g.name,pb.words(pb.withBook(Er.id,Er.g)),pb.SURE_WORDS[Er.e.sure]or tostring(Er.e.sure),tostring(Er.e.why)))
elseif Cr and Er.id==bb.trialId then
F.log(1,CJe[2641],string.format(CJe[2693],V.name(Er.id),Er.g.name,tostring(Er.miss)))
end
end
F.saveSoon()
end
