function kb.gainXp(ieb,jeb)
local keb,leb=tonumber(ieb.xp)or 0,kb.xpFor(ieb.unit_id,kb.cap(ieb))
local meb=math.max(0,leb-keb)
if meb<=0 or(jeb or 0)<=0 then
return 0,0
end
local neb=math.min(jeb,meb)
local oeb=kb.base(ieb)
if oeb<=0 then
return 0,neb
end
return kb.share(ieb.unit_id)*(kb.score(kb.whatIf(ieb,{xp=keb+neb}))/oeb-1)*100,neb
end
