function kb.relicWorth(peb,qeb)
local reb=qeb._unique_item_data and qeb._unique_item_data._unique_relic_data
if not reb then
return 0
end
local seb=N.Items[qeb.item_id]or{}
local teb,ueb=V.types(peb.unit_id)
if seb.main_damage_type and seb.main_damage_type~=CJe[2953]and seb.main_damage_type~=ueb then
return 0
end
local veb,web=0,0
for xeb,yeb in pairs(reb._core_damage_type_buffs or{})do
if teb[yeb.damage_type]then
veb=veb+(tonumber(yeb.mul)or 0)+(tonumber(yeb.add_upg)or 0)*0.01+(tonumber(yeb.pen)or 0)*0.001
web=web+(tonumber(yeb.crit)or 0)
end
end
veb=veb+web*0.5
local zeb=V.rows(peb.unit_id)
local Aeb=zeb and zeb[zeb.max]
local Beb=(Aeb and tonumber(Aeb.cd)or 0)*V.mult(peb,CJe[2703])
for Ceb,Deb in pairs(reb._unique_relic_effects or{})do
local Eeb=type(Deb.params)==CJe[2252]and Deb.params or{}
if Deb.id==CJe[3353]then
local Feb=math.min(1,(tonumber(Eeb.extra_damage)or 0)*Beb/math.max(1,tonumber(Eeb.time_interval)or 40))
local Geb=V.DRONES and V.DRONES[peb.unit_id]
if Geb and Geb.late and Beb>0 then
local Heb=1/Beb
Feb=Feb*Heb/(Heb+(tonumber(Geb.max)or 0)*(tonumber(Geb.late.dmg)or 0)*(tonumber(Geb.hits)or 1)/math.max(0.1,tonumber(Geb.late.cd)or 4))
end
veb=veb+Feb
elseif Deb.id==CJe[3354]then
veb=veb+(tonumber(Eeb.dmg_buff)or 0)*0.25
elseif Deb.id==CJe[3355]then
veb=veb+(tonumber(Eeb.dmg_buff)or 0)*web
elseif Deb.id==CJe[3356]then
if teb.magic then
veb=0
else
veb=veb+(tonumber(Eeb.dmg_buff)or 0)*0.3
end
elseif Deb.id==CJe[3357]then
if teb.water_damage then
veb=veb+0.05
end
elseif Deb.id==CJe[2404]then
local Ieb=tonumber(Eeb.duration_buff)or tonumber(type(Deb.static_params)==CJe[2252]and Deb.static_params.duration_buff)or 2
local Jeb,Keb=pcall(V.attackInfo,Aeb and Aeb.atk,Aeb and Aeb.range)
local Leb,Meb=Jeb and tonumber(Keb.burn)or 0,Jeb and tonumber(Keb.dot)or 0
if Leb<=0 then
local Neb,Oeb=pcall(pb.model,peb.unit_id,Jeb and Keb or nil,Aeb)
if Neb and type(Oeb)==CJe[2252]and(tonumber(Oeb.burnDot)or 0)>0 then
Leb,Meb=Oeb.burnDot,Meb+(tonumber(Oeb.dot)or 0)
end
end
veb=veb+Leb*math.max(0,Ieb-1)/(1+Meb)
end
end
return veb
end
function kb.relicPlan()
