pfb[vfb.e.uuid]=nil
sfb(tfb+1,ufb)
for wfb,xfb in ipairs(vfb.opts)do
local yfb=(N.Items[xfb.it.item_id]or{}).unique_equip
if not qfb[xfb.it.uuid]and not(yfb and rfb[xfb.it.item_id])then
qfb[xfb.it.uuid]=true
if yfb then
rfb[xfb.it.item_id]=true
end
pfb[vfb.e.uuid]=xfb.it.uuid
sfb(tfb+1,ufb+xfb.w+(xfb.it.uuid==vfb.e.u._equipped_relic and 0.01 or 0))
pfb[vfb.e.uuid]=nil
qfb[xfb.it.uuid]=nil
if yfb then
rfb[xfb.it.item_id]=nil
end
end
end
end
sfb(1,0)
