end
local ohb=math.min(9,tonumber(nhb.story_world_rank)or tonumber(mhb.rank)or 9)
local phb=tonumber(nhb.story_level_rank)or 6
local qhb=(mhb.kind==CJe[2301]and 1.5 or 1)*(ohb>5 and 2 or 1)
local rhb=2.1564^(ohb-1)*(40+10*phb)/qhb
if mhb.kind==CJe[2277]then
rhb=3*30*2.1564^(ohb-1)/qhb
