kb.reequip()
end
F.log(1,CJe[3387],string.format(CJe[3881],V.name(ICb.unit_id),(N.Items[JCb.item_id]or{}).name or tostring(JCb.item_id),ICb._equipped_relic==HCb and CJe[1171]or CJe[3882]))
end
P.relicOff[GCb]=nil
