function ab.equipTeam(RCb,SCb)
local TCb={}
for UCb,VCb in ipairs(V.equipped())do
TCb[VCb.uuid]=true
end
if not P.savedTeam then
local WCb={}
for XCb,YCb in ipairs(V.equipped())do
table.insert(WCb,YCb.uuid)
end
P.savedTeam=WCb
end
local ZCb,_Cb=pcall(ab.relicClash,RCb)
if not ZCb then
F.log(1,CJe[2261],CJe[3883]..tostring(_Cb))
end
local aDb={}
for bDb,cDb in ipairs(RCb)do
aDb[cDb]=true
end
local dDb,eDb=false,{}
for fDb=1,4 do
for gDb in pairs(TCb)do
if not aDb[gDb]then
local hDb,iDb=F.request(CJe[2865],CJe[2866],gDb)
table.insert(eDb,string.format(CJe[3884],V.name((N.session().collection:get_unit_by_uuid(gDb)or{}).unit_id or CJe[2503]),tostring(iDb)))
task.wait(0.8)
end
end
for jDb,kDb in ipairs(RCb)do
if not TCb[kDb]then
local lDb
if fDb>2 then
local mDb={}
for nDb,oDb in ipairs(V.equipped())do
mDb[oDb.slot]=true
end
for pDb=1,6 do
if not mDb[pDb]then
lDb=pDb
break
end
end
end
local qDb,rDb
if lDb then
qDb,rDb=F.request(CJe[3385],CJe[3386],kDb,lDb)
else
qDb,rDb=F.request(CJe[3385],CJe[3386],kDb)
end
table.insert(eDb,string.format(CJe[3885],V.name((N.session().collection:get_unit_by_uuid(kDb)or{}).unit_id or CJe[2503]),lDb and(CJe[3886]..lDb)or CJe[1171],tostring(qDb),tostring(rDb)))
task.wait(0.8)
end
end
local sDb=U.now()
while U.now()-sDb<3 and not ib.same(ib.team(),RCb)do
task.wait(0.25)
end
dDb=ib.same(ib.team(),RCb)
if dDb then
break
end
TCb={}
for tDb,uDb in ipairs(V.equipped())do
TCb[uDb.uuid]=true
end
end
W._sigAt=nil
if dDb then
F.log(1,CJe[3387],CJe[3887].. #RCb..CJe[3888]..tostring(SCb))
else
local vDb={}
for wDb,xDb in ipairs(V.equipped())do
table.insert(vDb,V.name(xDb.id))
end
F.log(1,CJe[3387],CJe[3889]..tostring(SCb)..CJe[3890]..table.concat(vDb,CJe[2376])..CJe[3891]..table.concat(eDb,CJe[2643]))
if not ab.refilling and#V.equipped()<6 then
ab.refilling=true
local yDb,zDb={},{}
for ADb,BDb in ipairs(V.equipped())do
zDb[BDb.uuid]=true
end
for CDb,DDb in ipairs(P.savedTeam or{})do
if not zDb[DDb]and N.session().collection:get_unit_by_uuid(DDb)then
table.insert(yDb,DDb)
end
end
local EDb=0
for FDb,GDb in ipairs(yDb)do
if#V.equipped()>=6 then
break
end
F.request(CJe[3385],CJe[3386],GDb)
task.wait(0.8)
local HDb=U.now()
while U.now()-HDb<3 and#V.equipped()<math.min(6,EDb+1+(6- #yDb))do
task.wait(0.25)
end
for IDb,JDb in ipairs(V.equipped())do
if JDb.uuid==GDb then
EDb=EDb+1
end
end
end
local KDb={}
for LDb,MDb in ipairs(V.equipped())do
table.insert(KDb,V.name(MDb.id))
end
F.log(1,CJe[3387],string.format(CJe[3892],EDb,table.concat(KDb,CJe[2376])))
W._sigAt=nil
ab.refilling=nil
end
end
F.saveSoon()
return dDb
end
function ab.ownSwap()
local NDb=P.ownSwap
if not NDb then
