end
if VDb and VDb.unit_id==NDb.into then
SDb=true
end
end
local WDb,XDb
for YDb,ZDb in pairs(PDb.profile_data.collection.owned_units)do
if ZDb.unit_id==NDb.into and(not WDb or(tonumber(ZDb.xp)or 0)>XDb)then
WDb,XDb=YDb,tonumber(ZDb.xp)or 0
end
end
if SDb or not RDb or not WDb then
P.ownSwap=nil
F.log(1,CJe[3387],string.format(CJe[3893],V.name(NDb.into),V.name(NDb.out),SDb and CJe[3894]or not RDb and CJe[3895]or CJe[3896]))
return F.saveSoon()
end
QDb[RDb]=WDb
local _Db=P.savedTeam
P.savedTeam=nil
if ab.equipTeam(QDb,string.format(CJe[3897],V.name(NDb.into),V.name(NDb.out)))then
P.savedTeam,P.ownSwap=nil,nil
W.lastScored=nil
if F.notify then
F.notify(CJe[3898],string.format(CJe[3899],V.name(NDb.into),V.name(NDb.out)),CJe[3223])
end
else
P.savedTeam=_Db or P.savedTeam
end
F.saveSoon()
end
function ab.restoreTeam()
