ab.LAB={EVERY=3,KINDS={story=true,raid=true,infinite=true},MIN_EVIDENCE=5,AGAIN=3600}
function ab.unitEvidence(fEb)
local gEb=P.learn[fEb]
local hEb=gEb and tonumber(gEb.n)or 0
local iEb=db.hive()
local jEb=iEb and type(iEb.units)==CJe[2252]and iEb.units[fEb]
if type(jEb)==CJe[2252]then
hEb=hEb+(tonumber(jEb.matches)or 0)+(tonumber(jEb.matches3)or 0)
end
return hEb
end
function ab.unitLabSafe(kEb)
if O.unitLab==false or type(kEb)~=CJe[2252]or not ab.LAB.KINDS[kEb.kind]or kEb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==CJe[2252]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=CJe[1177]then
return false
end
local lEb,mEb=pcall(ab.matchOn,kEb)
if lEb and mEb then
return false
end
local nEb=type(P.unitLab)==CJe[2252]and P.unitLab or{}
if nEb.pauseKey==kEb.key and os.time()<(tonumber(nEb.pauseUntil)or 0)then
return false
end
local oEb=W.rec(kEb.key)
local pEb,qEb=tonumber(oEb.runs)or 0,tonumber(oEb.wins)or 0
if kEb.kind==CJe[2277]then
local rEb,sEb=pcall(W.infDaily,N.prof(),kEb.level,W.infReach(kEb.key))
return pEb>=3 and rEb and(tonumber(sEb)or 1)<=0
end
return pEb>=5 and(tonumber(oEb.streak)or 0)==0 and qEb/pEb>=0.9
end
function ab.unitLab(tEb)
if not ab.unitLabSafe(tEb)then
return
end
P.unitLab=type(P.unitLab)==CJe[2252]and P.unitLab or{}
local uEb=P.unitLab
uEb.tried=type(uEb.tried)==CJe[2252]and uEb.tried or{}
uEb.seen=(tonumber(uEb.seen)or 0)+1
if uEb.seen%ab.LAB.EVERY~=0 then
return
end
local vEb=N.session()
local wEb=V.equipped()
if not vEb or#wEb<2 then
return
end
local xEb={}
for yEb,zEb in ipairs(wEb)do
xEb[zEb.uuid]=true
xEb[zEb.id]=true
end
local AEb,BEb,CEb
for DEb,EEb in pairs(vEb.profile_data.collection.owned_units)do
local FEb=EEb.unit_id
if not xEb[DEb]and not xEb[FEb]and N.Units[FEb]and not V.isFarm(FEb)and not V.allyBuff(FEb)and os.time()-(tonumber(uEb.tried[FEb])or 0)>ab.LAB.AGAIN then
local GEb=ab.unitEvidence(FEb)
if GEb<ab.LAB.MIN_EVIDENCE then
local HEb=vEb.collection:get_unit_by_uuid(DEb)or EEb
local IEb=kb.score(HEb)
if IEb>0 and(not AEb or GEb<BEb or(GEb==BEb and IEb>CEb))then
AEb,BEb,CEb={uuid=DEb,id=FEb,u=HEb},GEb,IEb
end
end
end
end
if not AEb then
return
end
local JEb,KEb
for LEb,MEb in ipairs(wEb)do
if not V.isFarm(MEb.id)and not V.allyBuff(MEb.id)and MEb.uuid~=O.evolveUnit then
local NEb=kb.score(MEb.u)
if not JEb or NEb<KEb then
JEb,KEb=MEb,NEb
end
end
end
if not JEb then
return
end
uEb.tried[AEb.id]=os.time()
local OEb=0
for PEb in pairs(uEb.tried)do
OEb=OEb+1
if OEb>300 then
uEb.tried[PEb]=nil
end
end
local QEb,REb=gb.levelFor(tEb)
if not QEb then
return
end
local SEb=gb.info(QEb,tEb.key,REb,tEb.mod or W.ldMod(QEb)or W.levelMod(tEb.level))
local TEb={}
for UEb,VEb in ipairs(wEb)do
table.insert(TEb,VEb.uuid==JEb.uuid and AEb.u or VEb.u)
end
local WEb,XEb=pcall(gb.run,SEb,gb.teamFrom(TEb,SEb.map),{hpMul=1.1})
local YEb=WEb and type(XEb)==CJe[2252]and(XEb.won or(SEb.infinite and(tonumber(XEb.wave)or 0)>=0.8*W.infReach(tEb.key)))
if not YEb then
F.log(2,CJe[3902],string.format(CJe[3903],V.name(AEb.id),tEb.label))
return
end
local ZEb={}
for _Eb,aFb in ipairs(wEb)do
table.insert(ZEb,aFb.uuid==JEb.uuid and AEb.uuid or aFb.uuid)
end
if ab.equipTeam(ZEb,CJe[3904]..V.name(AEb.id))then
uEb.now={id=AEb.id,out=JEb.id,key=tEb.key,at=os.time(),ev=BEb}
F.log(1,CJe[3902],string.format(CJe[3905],V.name(AEb.id),V.name(JEb.id),tEb.label,BEb))
F.saveNow()
end
end
function ab.unitLabDone(bFb)
