function eb.upgradeGain(iKb,jKb,kKb,lKb,mKb,nKb)
local oKb,pKb=jKb[kKb],jKb[kKb+1]
local qKb=(oKb.cd>0 and oKb.damage/oKb.cd or 0)
local rKb=(pKb.cd>0 and pKb.damage/pKb.cd or 0)*V.aoe(pKb.atk,pKb.range)/math.max(0.3,V.aoe(oKb.atk,oKb.range))
local sKb=qKb>0 and iKb*(rKb/qKb-1)or(nKb or 0)
local tKb=jKb[kKb+2]
if tKb and kKb+1<jKb.max and tKb.cd>0 and pKb.cd>0 and qKb>0 then
local uKb=iKb*((tKb.damage/tKb.cd)/qKb-1)
local vKb=lKb+tKb.cost*mKb
if uKb/vKb>sKb/lKb then
sKb=sKb+(uKb/vKb*lKb-sKb)*0.5
end
end
local wKb=(pKb.range or 0)>(oKb.range or 0)and(1+((pKb.range-oKb.range)/math.max(1,oKb.range)))or 1
return math.max(0,sKb)*wKb
end
function eb.dpsFor(xKb,yKb)
if yKb<=0 then
return 0
end
local zKb={}
for AKb,BKb in ipairs(xKb)do
if not BKb.farm and not BKb.grif and BKb.gain>0 then
table.insert(zKb,BKb)
end
end
table.sort(zKb,function(CKb,DKb)
return CKb.gain/CKb.cost>DKb.gain/DKb.cost
end)
local EKb,FKb=0,0
for GKb,HKb in ipairs(zKb)do
if yKb<=0 then
break
end
FKb=HKb.gain/HKb.cost
local IKb=math.min(1,yKb/HKb.cost)
EKb=EKb+HKb.gain*IKb
yKb=yKb-HKb.cost*IKb
end
return EKb+math.max(0,yKb)*FKb*0.7
end
function eb.shieldDps(JKb,KKb,LKb,MKb,NKb,OKb,PKb)
if(MKb or 0)<=0 or(JKb or 0)<=0 or(NKb or 0)<=0 then
return JKb or 0
end
KKb,LKb,OKb=math.max(0.3,KKb or 2),math.max(1,LKb or 1),OKb or 1
local QKb=JKb*OKb*KKb/LKb
return NKb*LKb/((MKb/math.max(1,PKb or 1)+math.max(1,NKb/QKb))*KKb)/OKb
end
function eb.shieldGain(RKb,SKb,TKb,UKb,VKb,WKb,XKb,YKb)
local ZKb,_Kb=V.attackInfo(SKb.atk,SKb.range),V.attackInfo(UKb.atk,UKb.range)
local aLb=eb.shieldDps(RKb,(tonumber(SKb.cd)or 2)*(XKb or 1),ZKb.n,VKb,WKb,YKb,ZKb.hits)
local bLb=eb.shieldDps(TKb,(tonumber(UKb.cd)or 2)*(XKb or 1),_Kb.n,VKb,WKb,YKb,_Kb.hits)
local cLb=math.max(0,((tonumber(UKb.range)or 0)-(tonumber(SKb.range)or 0))/math.max(1,tonumber(SKb.range)or 1))
return math.max(0,bLb-aLb)+aLb*cLb
end
function eb.shieldWork(dLb,eLb,fLb,gLb,hLb,iLb,jLb,kLb,lLb)
if(gLb or 0)<=0 then
return 0
end
local mLb=3*gLb*(hLb or 1)/math.max(1,iLb or 20)
if(fLb or 0)>=mLb then
return 0
end
return math.max(1,dLb or 1)*math.max(1,lLb or 1)/math.max(0.3,eLb or 2)*math.min(jLb or 0,kLb or 0)
end
function eb.holdGain(nLb,oLb,pLb,qLb)
if not nLb or(oLb or 0)<=0 then
return 0
end
local rLb,sLb=tonumber(nLb.stun)or 0,tonumber(nLb.slowTime)or 0
if rLb<=0 and sLb<=0 then
return 0
end
local tLb,uLb=rLb>0 and rLb or sLb,rLb>0 and 1 or(tonumber(nLb.slowPct)or 0.3)
local vLb=uLb*tLb/(tLb+(tonumber(nLb.ccCd)or 8))
local wLb=vLb/math.max(0.1,1-vLb)
return oLb*wLb*U.clamp(pLb or 0.5,0,1)*math.min(1,(tonumber(nLb.n)or 1)/2)/(1+(qLb or 0))
end
function eb.bleedGain(xLb,yLb,zLb,ALb)
if(xLb or 0)<=0 then
return 0
end
local BLb=yLb or 0
for CLb,DLb in ipairs(zLb or{})do
BLb=math.max(BLb,(tonumber(DLb.hp)or 0)*0.5)
end
return xLb*BLb*(ALb and 0.5 or 1)
end
function eb.bleedShare(ELb,FLb,GLb,HLb)
if ELb<=0 or not FLb then
return 0
end
if HLb then
return FLb==0 and ELb or ELb/(FLb+1)
end
return GLb<FLb and ELb/(FLb-GLb)or 0
end
function eb.keepsUp(ILb,JLb,KLb,LLb,MLb)
local NLb=ILb.coming
if not(NLb and#NLb>0 and ILb.waveSec)then
return true
end
local OLb=ILb.eff or 1
local PLb=ILb.money-KLb
local QLb=(ILb.teamDps or 0)*(ILb.shieldK or 1)+(LLb or 0)*OLb+eb.dpsFor(JLb,math.max(0,PLb))*OLb
local RLb=(ILb.farmNow or 0)+(MLb or 0)
local SLb=(ILb.roadSec or 130)*U.clamp(ILb.cover or 0.6,0.1,1)
local TLb=ILb.hpAlive or 0
for ULb,VLb in ipairs(NLb)do
TLb=math.max(0,TLb+VLb.hp-QLb*ILb.waveSec)
local WLb=QLb*SLb
if TLb>WLb then
return false,ULb,WLb/math.max(1,TLb)
end
if ULb< #NLb then
QLb=QLb+eb.dpsFor(JLb,(VLb.reward or 0)+RLb)*OLb*(0.85^ULb)
end
end
return true
end
function eb.decide(XLb,YLb)
local ZLb=U.clamp(YLb.cover or 0.6,0.1,1)
local _Lb=math.max(O.clearSec,0.7*(YLb.roadSec or 50)*ZLb)
local aMb=(YLb.clearSec or 0)>_Lb
YLb.piling=YLb.piling and aMb
local bMb=YLb.attackers>0 and YLb.pressure<math.min(O.safeReach,ZLb*0.75)and not YLb.piling and not aMb
local cMb=YLb.pressure>=math.min(O.dangerReach,ZLb*0.9)or(YLb.piling and YLb.enemies>=18)
local dMb,eMb
for fMb,gMb in ipairs(XLb)do
if gMb.farm then
if O.farmUnits and gMb.gain>0 then
gMb.payback=gMb.cost/gMb.gain
if YLb.left-1>=gMb.payback+(YLb.farmSpare or O.farmSpare)and(not dMb or gMb.payback<dMb.payback)then
dMb=gMb
end
end
else
gMb.ratio=gMb.gain/math.max(1,gMb.cost)
if not eMb or gMb.ratio>eMb.ratio then
eMb=gMb
end
end
end
if YLb.leak and YLb.attackers>0 then
local hMb
for iMb,jMb in ipairs(XLb)do
local kMb=not YLb.airLeak or(jMb.e and bb.cardAir(jMb.e.id))
if jMb.place and not jMb.farm and not jMb.idol and not jMb.grif and kMb and jMb.cost<=YLb.money and not(jMb.e and V.allyBuff(jMb.e.id))and(not hMb or jMb.gain>hMb.gain)then
hMb=jMb
