end
if hMb then
return hMb,string.format(CJe[4048],math.floor(YLb.leak*100))
end
end
local lMb=YLb.future<YLb.wantLeft*1.1
local mMb,nMb,oMb=true,nil,nil
if dMb then
mMb,nMb,oMb=eb.keepsUp(YLb,XLb,dMb.cost,0,dMb.gain)
end
local pMb=YLb.coming and not eb.keepsUp(YLb,XLb,0,0,0)
local qMb=false
if bb.random and dMb and not cMb and YLb.attackers>=2 and dMb.payback<=YLb.left/3 then
local rMb=0
for sMb,tMb in ipairs(bb.mine or{})do
if V.isFarm(tMb._stats.id.Value)then
rMb=rMb+1
end
end
qMb=not dMb.place or rMb<4
end
if pMb and YLb.attackers>0 then
cMb=true
end
if cMb and eMb and eMb.grif then
eMb=nil
for uMb,vMb in ipairs(XLb)do
if not vMb.farm and not vMb.grif and(not eMb or vMb.ratio>eMb.ratio)then
eMb=vMb
end
end
