end
return fqc>0 and gqc/fqc or 0.5
end
function jb.itemValue(pqc,qqc)
local rqc=jb.item(pqc)
if not rqc or jb.isCurse(pqc)then
return 0
end
local sqc=0
if tonumber(rqc.luck_increase)then
sqc=sqc+300*rqc.luck_increase
end
if tonumber(rqc.star_remnant_chest_add)then
sqc=sqc+150*rqc.star_remnant_chest_add
end
if pqc==CJe[4302]then
local tqc,uqc=jb.res(qqc)
sqc=sqc+60+25*uqc
end
if pqc==CJe[4303]then
sqc=sqc+120
end
for vqc,wqc in pairs(type(rqc.wave_modifier_effects)==CJe[2252]and rqc.wave_modifier_effects or{})do
local xqc=math.abs(tonumber(wqc.amount)or 0)
if wqc.type==CJe[4304]and wqc.stat==CJe[2702]then
sqc=sqc+100*xqc
elseif wqc.type==CJe[4304]and wqc.stat==CJe[2703]then
sqc=sqc+100*xqc/math.max(0.2,1-xqc)
elseif wqc.type==CJe[4304]and wqc.stat==CJe[2520]then
sqc=sqc+50*xqc
elseif wqc.type==CJe[4305]and wqc.stat==CJe[4306]then
sqc=sqc+100*xqc*jb.share(CJe[2442])
elseif wqc.type==CJe[4305]and wqc.stat==CJe[4307]then
sqc=sqc+100*xqc*jb.share(CJe[2440])
elseif wqc.type==CJe[4305]and wqc.stat==CJe[4308]then
sqc=sqc+100*xqc*jb.share(CJe[4160])
elseif wqc.type==CJe[4309]and wqc.stat==CJe[4310]then
sqc=sqc+60*xqc*jb.share(CJe[2442])
elseif wqc.type==CJe[4311]then
sqc=sqc+40*xqc
elseif wqc.type==CJe[4312]then
sqc=sqc+80*xqc
elseif wqc.type==CJe[4313]then
sqc=sqc+80*xqc
end
end
return sqc
end
jb.CURSE_COST={_curse_money=0.5,_curse_shop=0.5,_curse_health=0.5,_curse_speed=0.5,_curse_regen=0.5,_curse_shield=1,_curse_explode=1.5,_curse_random=2,_curse_super_health=1,_curse_super_speed=1,_curse_super_regen=1,_curse_super_armored=3,_curse_super_burst=1,_curse_super_explode=3,_curse_super_chaos=3}
function jb.curseCost(yqc)
if yqc==CJe[4314]then
local zqc,Aqc=0,0
for Bqc,Cqc in ipairs(V.equipped())do
local Dqc=Cqc.id or(Cqc.u and Cqc.u.unit_id)
if Dqc and not V.isFarm(Dqc)then
zqc=zqc+1
local Eqc,Fqc=pcall(V.airFrom,Dqc)
if Eqc and Fqc then
Aqc=Aqc+(Fqc==0 and 1 or 0.5)
end
end
end
return 1+2*(zqc>0 and 1-Aqc/zqc or 0.5)
end
return jb.CURSE_COST[yqc]or 1.5
end
function jb.roomValue(Gqc,Hqc)
local Iqc,Jqc=Gqc.tags,Gqc.d
local Kqc=0
if Iqc[jb.T.GOLD]then
Kqc=Kqc+12
end
if Iqc[jb.T.CHEST]then
Kqc=Kqc+4
end
if Iqc[jb.T.MONEY]then
Kqc=Kqc+(Jqc<=15 and 2 or 0.5)
end
if Iqc[jb.T.SHOP]then
if Jqc>=10 and Jqc<=15 then
Kqc=Kqc+(Hqc>=300 and 5 or 1)
else
Kqc=Kqc+(Hqc>=300 and(Jqc>15 and 3 or 1)or 0.3)
end
end
if Iqc[jb.T.SHRINE]then
Kqc=Kqc+1.5
end
if Iqc[jb.T.CURSE]then
Kqc=Kqc-jb.curseCost(jb.roomCurse(Gqc.r))
end
return Kqc
end
function jb.mod(Lqc)
local Mqc={weak={},strong={}}
for Nqc,Oqc in pairs(type(Lqc)==CJe[2252]and type(Lqc._weak_against)==CJe[2252]and Lqc._weak_against or{})do
if type(Oqc)==CJe[2252]and Oqc.damage_type then
Mqc.weak[Oqc.damage_type]=W.weakAmp(Oqc.amplification)
end
end
for Pqc,Qqc in pairs(type(Lqc)==CJe[2252]and type(Lqc._strong_against)==CJe[2252]and Lqc._strong_against or{})do
Mqc.strong[type(Qqc)==CJe[2252]and Qqc.damage_type or Qqc]=true
end
return(next(Mqc.weak)or next(Mqc.strong))and Mqc or nil
end
function jb.roomCurse(Rqc)
local Sqc=type(Rqc)==CJe[2252]and type(Rqc._t)==CJe[2252]and Rqc._t or{}
local Tqc=Sqc[0]or Sqc[CJe[4315]]
return type(Tqc)==CJe[2252]and Tqc.id or nil
end
function jb.fx(Uqc,Vqc,Wqc)
local Xqc={dmg=1,cd=1,range=1,cost=1,hp=1,speed=1,regen=0,crit=0,kinds={},shield=0,fly=0}
