local arc=jb.item(Zqc)
for brc,crc in pairs(type(arc and arc.wave_modifier_effects)==CJe[2252]and arc.wave_modifier_effects or{})do
local drc=(tonumber(crc.amount)or 0)*_qc
if crc.type==CJe[4304]and crc.stat==CJe[2702]then
Xqc.dmg=Xqc.dmg+drc
elseif crc.type==CJe[4304]and crc.stat==CJe[2703]then
Xqc.cd=Xqc.cd+drc
elseif crc.type==CJe[4304]and crc.stat==CJe[2520]then
Xqc.range=Xqc.range+drc
elseif crc.type==CJe[4305]and tostring(crc.stat):sub(1,9)==CJe[4316]then
local erc=tostring(crc.stat):sub(10)
Xqc.kinds[erc]=(Xqc.kinds[erc]or 0)+drc
elseif crc.type==CJe[4309]and crc.stat==CJe[4310]then
Xqc.crit=Xqc.crit+drc
elseif crc.type==CJe[4313]then
Xqc.cost=Xqc.cost+drc
elseif crc.type==CJe[4317]and crc.stat==CJe[3862]then
Xqc.hp=Xqc.hp+drc
elseif crc.type==CJe[4312]then
Xqc.speed=Xqc.speed+drc
elseif crc.type==CJe[4318]then
Xqc.regen=Xqc.regen+drc
elseif crc.type==CJe[4319]then
Xqc.shield=Xqc.shield+drc
elseif crc.type==CJe[4320]and crc.passive==CJe[4321]then
Xqc.fly=Xqc.fly+drc
elseif crc.type==CJe[4320]and crc.passive==CJe[4322]then
Xqc.burst=(Xqc.burst or 0)+drc
end
end
end
Xqc.cd,Xqc.cost,Xqc.speed=math.max(0.1,Xqc.cd),math.max(0.1,Xqc.cost),math.max(0.1,Xqc.speed)
return Xqc
end
function jb.fxText(frc)
local grc={}
local function hrc(irc,jrc)
if math.abs(jrc-1)>0.001 then
table.insert(grc,string.format(CJe[4184],irc,jrc))
end
end
hrc(CJe[2702],frc.dmg)
hrc(CJe[3059],frc.cd)
hrc(CJe[2520],frc.range)
hrc(CJe[4323],frc.cost)
for krc,lrc in pairs(frc.kinds)do
table.insert(grc,string.format(CJe[2789],krc,math.floor(lrc*100+0.5)))
end
if frc.crit>0 then
table.insert(grc,string.format(CJe[4211],math.floor(frc.crit*100+0.5)))
end
hrc(CJe[4324],frc.hp)
hrc(CJe[4325],frc.speed)
if frc.regen>0 then
table.insert(grc,string.format(CJe[4326],math.floor(frc.regen*100+0.5)))
end
if frc.shield>0 then
table.insert(grc,string.format(CJe[4327],math.floor(frc.shield+0.5)))
end
if frc.fly>0 then
table.insert(grc,string.format(CJe[4328],math.floor(frc.fly*100+0.5)))
end
if(frc.burst or 0)>0 then
table.insert(grc,string.format(CJe[4329],math.floor(frc.burst*100+0.5)))
end
return#grc>0 and table.concat(grc,CJe[2376])or CJe[2851]
end
function jb.sim(mrc,nrc,orc)
if not O.sim or type(mrc.r._l)~=CJe[2252]then
return nil
end
local prc=tostring(mrc.r._r or(mrc.d..CJe[2405]..mrc.choice))..(nrc and(CJe[2582]..tostring(nrc))or CJe[1171])..(orc and CJe[4330]or CJe[1171])
local qrc=jb.data()
local rrc=jb.fx(qrc,jb.roomCurse(mrc.r),nrc)
local trc=W.teamSig()..CJe[2265]..jb.fxText(rrc)..(O.killZone~=false and CJe[4331]or CJe[1171])..(bb.forcedWay()and(CJe[2265]..tostring(O.placeMode))or CJe[1171])
local urc=P.dg.sim[prc]
if urc and urc.sig==trc then
return not urc.none and urc or nil
end
local vrc={}
for wrc,xrc in ipairs(V.equipped())do
table.insert(vrc,xrc.u)
end
if#vrc==0 then
return nil
end
local yrc=gb.applyFx(gb.info(gb.slim(mrc.r._l),CJe[3010],nil,jb.mod(mrc.r._l)),rrc)
jb.applyK(yrc,mrc.r._r)
if orc then
yrc.zone=false
end
local zrc=gb.wave(yrc,1,true)
if#zrc==0 then
urc={none=true,sig=trc,at=os.time()}
else
local Arc=gb.evaluate(yrc,gb.teamFrom(vrc,yrc.map))
urc={p=Arc.p,wave=Arc.wave,won=Arc.won,total=yrc.total,margin=Arc.margin,sig=trc,at=os.time(),zone=yrc.zone~=false or nil}
end
P.dg.sim[prc]=urc
if U.count(P.dg.sim)>60 then
local Brc,Crc
for Drc,Erc in pairs(P.dg.sim)do
if not Crc or(Erc.at or 0)<Crc then
Brc,Crc=Drc,Erc.at or 0
end
end
P.dg.sim[Brc]=nil
end
F.saveSoon()
return not urc.none and urc or nil
end
function jb.winP(Frc)
local Grc=tostring(math.min(4,math.max(1,math.ceil(Frc.d/5))))
local Hrc=P.dg.depth[Grc]or{runs=0,wins=0}
local Irc=U.clamp(0.95-0.015*Frc.d,0.5,0.95)
local Jrc=((tonumber(Hrc.wins)or 0)+Irc*2)/((tonumber(Hrc.runs)or 0)+2)
local Krc,Lrc=pcall(jb.sim,Frc)
if Krc and Lrc and Lrc.p then
local Mrc,Nrc=pcall(gb.styleP,Lrc,Lrc.zone==false and CJe[4174]or(Lrc.zone and CJe[4108]or nil))
Jrc=(Jrc*2+(Mrc and Nrc or Lrc.p))/3
end
return Jrc,Krc and Lrc or nil
end
function jb.hopeless(Orc)
return Orc~=nil and Orc.won==false and(tonumber(Orc.p)or 1)<=0.05
end
function jb.stake(Prc)
local Qrc,Rrc,Src=jb.res(Prc)
return Rrc+2*Src
end
function jb.curseBar(Trc,Urc)
local Vrc=jb.stake(Trc)
if Urc>=15 or Vrc>=8 then
return 0.9,CJe[4332],Vrc
end
if Urc>=10 or Vrc>=4 then
return 0.6,CJe[4333],Vrc
end
return 0.1,CJe[4334],Vrc
end
function jb.blindCurse(Wrc,Xrc)
return jb.fxText(jb.fx(Wrc,Xrc))==jb.fxText(jb.fx(Wrc))
end
function jb.curseOk(Yrc,Zrc,_rc,asc,bsc)
local csc=tostring((jb.item(Yrc)or{}).name or Yrc)
local dsc,esc,fsc=jb.curseBar(Zrc,_rc)
if dsc>0.2 and jb.blindCurse(Zrc,Yrc)then
return false,string.format(CJe[4335],csc,fsc)
end
local function gsc(hsc)
return hsc==nil or(tonumber(hsc.p)or 1)>=dsc
end
if asc then
local isc,jsc=pcall(jb.sim,asc,nil,true)
if isc and not gsc(jsc)then
return false,string.format(CJe[4336],csc,(esc:gsub(CJe[3938],CJe[4337])),tostring(jsc.margin or CJe[2503]))
end
end
if#bsc==0 then
return true
end
local ksc
for lsc,msc in ipairs(bsc)do
local nsc,osc=pcall(jb.sim,msc,Yrc,true)
if not nsc or gsc(osc)then
return true
end
if not ksc or(tonumber(osc.p)or 0)>(tonumber(ksc.p)or 0)then
ksc=osc
end
end
return false,string.format(CJe[4338],csc,esc,tostring(ksc and ksc.margin or CJe[2503]))
end
function jb.curseGate(psc,qsc)
local rsc=jb.roomCurse(psc.r)
if not rsc then
return true
end
return jb.curseOk(rsc,qsc,psc.d,psc,jb.after(qsc,psc.choice))
end
function jb.payValue()
local ssc,tsc=0,0
for usc,vsc in ipairs(P.dg.pay or{})do
if type(vsc.items)==CJe[2252]then
local wsc=tonumber(vsc.gems)or 0
for xsc,ysc in pairs(vsc.items)do
if(tonumber(ysc)or 0)>0 then
wsc=wsc+W.itemValue(xsc,ysc)
end
end
ssc,tsc=ssc+wsc,tsc+1
end
end
if tsc<5 then
return nil
end
return ssc/tsc*0.7
end
jb.LOSS_PRIOR={won=3,n=12}
function jb.lossWin()
local zsc=type(P.dg)==CJe[2252]and type(P.dg.lossCalls)==CJe[2252]and P.dg.lossCalls or{}
return U.clamp(((tonumber(zsc.won)or 0)+jb.LOSS_PRIOR.won)/((tonumber(zsc.n)or 0)+jb.LOSS_PRIOR.n),0.05,0.95)
end
function jb.pick(Asc)
local Bsc,Csc=jb.curses(Asc),jb.lives(Asc)
local Dsc=jb.res(Asc)
local Esc=jb.rooms(Asc)
local Fsc={}
for Gsc,Hsc in ipairs(Esc)do
table.insert(Fsc,tostring(Hsc.r._r))
end
local Isc=table.concat(Fsc,CJe[3151])..string.format(CJe[4339],Csc,Dsc,Bsc,W.teamSig())
if jb._pick and jb._pick.sig==Isc then
return jb._pick.x
end
local Jsc,Ksc,Lsc,Msc
for Nsc,Osc in ipairs(Esc)do
local Psc=jb.roomValue(Osc,Dsc)
local Qsc,Rsc
for Ssc,Tsc in ipairs(jb.after(Asc,Osc.choice))do
local Usc=jb.roomValue(Tsc,Dsc)
if not Qsc or Usc>Qsc then
Qsc,Rsc=Usc,Tsc
end
end
local Vsc,Wsc=jb.winP(Osc)
local Xsc=Wsc~=nil and Wsc.won==false
local Ysc=Csc>=3 and 1 or(Csc==2 and 2 or 6)
local Zsc=1-(1-Vsc)^math.max(1,Csc)
Osc.oldScore=Zsc*(Psc+0.6*(Qsc or 0))-(1-Vsc)*Ysc
if Xsc then
Vsc=math.min(Vsc,jb.lossWin())
Zsc=Vsc
Ysc=Ysc*2
end
Osc.p,Osc.sim,Osc.value,Osc.nextValue,Osc.nextRoom,Osc.simLost=Vsc,Wsc,Psc,Qsc or 0,Rsc,Xsc or nil
Osc.score=Zsc*(Psc+0.6*(Qsc or 0))-(1-Vsc)*Ysc
local _sc,atc,btc=pcall(jb.curseGate,Osc,Asc)
if _sc and not atc then
Osc.blocked=btc
end
if not Osc.blocked then
if not Jsc or Osc.score>Jsc.score then
Jsc=Osc
end
if Xsc then
if not Msc or Osc.score>Msc.score then
Msc=Osc
end
elseif not Lsc or Osc.score>Lsc.score then
Lsc=Osc
end
end
if not Ksc or Osc.score>Ksc.score then
Ksc=Osc
end
end
if Jsc and Jsc.simLost and Lsc then
F.log(1,CJe[4340],string.format(CJe[4341],jb.roomName(Jsc),tostring(Jsc.sim and Jsc.sim.margin or CJe[2503]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(Lsc)))
elseif Jsc and Msc and Msc~=Jsc and Msc.oldScore>Jsc.score then
F.log(1,CJe[4340],string.format(CJe[4342],jb.roomName(Msc),tostring(Msc.sim and Msc.sim.margin or CJe[2503]),jb.roomName(Jsc)))
end
Jsc=Jsc or Ksc
jb._pick={sig=Isc,x=Jsc,rooms=Esc}
return Jsc
end
function jb.roomName(ctc)
local dtc=type(ctc.r._l)==CJe[2252]and ctc.r._l or{}
return string.format(CJe[4343],tostring(dtc._location_name or dtc.map or CJe[2503]),jb.tagText(ctc.tags))
end
function jb.screens(etc)
