for gtc,htc in pairs(type(etc.current_shops)==CJe[2252]and etc.current_shops or{})do
if type(htc)==CJe[2252]then
table.insert(ftc,{i=tonumber(gtc)or 0,t=tonumber(htc._t),data=htc.data})
end
end
table.sort(ftc,function(itc,jtc)
return itc.i<jtc.i
end)
