function jb.logState(ntc,otc)
local ptc={}
for qtc,rtc in pairs(ntc)do
if not jb.KNOWN[qtc]and not(type(rtc)==CJe[2252]and next(rtc)==nil)then
table.insert(ptc,tostring(qtc))
end
end
table.sort(ptc)
local stc={}
for ttc,utc in ipairs(jb.screens(ntc))do
table.insert(stc,tostring(utc.t))
end
local vtc=table.concat(ptc,CJe[3151])..(#stc>0 and(CJe[2394]..table.concat(stc,CJe[3151]))or CJe[1171])
if vtc==CJe[1171]or P.dg.seen[vtc]then
return
end
P.dg.seen[vtc]=os.time()
local wtc={}
for xtc,ytc in ipairs(ptc)do
local ztc=ntc[ytc]
table.insert(wtc,ytc..CJe[2936]..(type(ztc)==CJe[2252]and U.json(U.plain(ztc)):sub(1,500)or tostring(ztc)))
end
F.log(1,CJe[4340],CJe[4348]..tostring(otc)..CJe[4349]..table.concat(wtc,CJe[2643]))
F.saveSoon()
