function jb.offers(Btc,Ctc)
local Dtc={}
if type(Btc)~=CJe[2252]then
return Dtc
end
for Etc,Ftc in pairs(Btc)do
local Gtc,Htc
if type(Ftc)==CJe[2252]then
Gtc=Ftc.id or Ftc.item_id or Ftc.item
Htc=tonumber(Ftc.cost)or tonumber(Ftc.price)
elseif type(Ftc)==CJe[1157]then
Gtc=Ftc
elseif jb.item(Etc)then
Gtc=Etc
Htc=tonumber(Ftc)
end
if type(Gtc)==CJe[1157]and jb.item(Gtc)then
table.insert(Dtc,{key=Etc,id=Gtc,cost=Htc or tonumber(jb.item(Gtc).cost)or 0,bought=type(Ftc)==CJe[2252]and(Ftc.bought or Ftc.sold or Ftc.purchased)or nil})
end
end
if#Dtc==0 and not Ctc then
for Itc,Jtc in pairs(Btc)do
if type(Jtc)==CJe[2252]then
Dtc=jb.offers(Jtc,true)
if#Dtc>0 then
break
end
end
end
end
return Dtc
end
function jb.buy(Ktc)
local Ltc=jb.res(jb.data())
local Mtc={}
if P.dg.buyArg==CJe[2645]then
Mtc={Ktc.id,Ktc.key}
else
Mtc={Ktc.key,Ktc.id}
end
if Mtc[1]==Mtc[2]then
Mtc[2]=nil
end
for Ntc,Otc in ipairs(Mtc)do
local Ptc,Qtc=F.request(CJe[4350],CJe[3964],Otc)
local Rtc=U.now()
while U.now()-Rtc<3 and jb.res(jb.data())>=Ltc do
task.wait(0.25)
end
if jb.res(jb.data())<Ltc then
P.dg.buyArg=(Otc==Ktc.id and Ktc.id~=Ktc.key)and CJe[2645]or CJe[4351]
return true
end
if not Ptc then
break
end
end
return false
end
function jb.shopAhead(Stc)
for Ttc,Utc in ipairs(jb.rooms(Stc))do
if Utc.tags[jb.T.SHOP]then
return true
end
for Vtc,Wtc in ipairs(jb.after(Stc,Utc.choice))do
if Wtc.tags[jb.T.SHOP]then
return true
end
end
end
return false
end
jb.LUCK_RESERVE=500
jb.MIN_WORTH=0.02
jb.TOP_WORTH=0.08
function jb.shop(Xtc,Ytc)
local Ztc=jb.cleared(Xtc)
local _tc=jb.res(Xtc)
local auc=1+0.1*(jb.items(Xtc)._curse_shop or 0)
local buc=jb.shopAhead(Xtc)and math.ceil(jb.LUCK_RESERVE*auc)or 0
local cuc={}
local duc,euc={},0
for fuc,guc in ipairs(jb.offers(Ytc and Ytc.data))do
guc.cost=math.ceil(guc.cost*auc)
table.insert(duc,tostring(jb.item(guc.id).name or guc.id))
if not guc.bought and not jb.isCurse(guc.id)then
guc.luck=tonumber(jb.item(guc.id).luck_increase)~=nil
guc.v=jb.itemValue(guc.id,Xtc)
