function bb.buildPath()
bb.samples={}
local AAc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not AAc then
return
end
for BAc,CAc in pairs(AAc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[BAc.Name])then
local DAc={}
for EAc,FAc in ipairs(CAc.points or{})do
table.insert(DAc,FAc.part.Position)
end
local GAc=0
for HAc=2,#DAc do
GAc=GAc+(DAc[HAc]-DAc[HAc-1]).Magnitude
end
local IAc=0
for JAc=2,#DAc do
local KAc,LAc=DAc[JAc-1],DAc[JAc]
local MAc=(LAc-KAc).Magnitude
local NAc=math.max(1,math.floor(MAc/2))
for OAc=0,NAc-1 do
local PAc=KAc:Lerp(LAc,OAc/NAc)
table.insert(bb.samples,{pos=PAc,prog=(IAc+MAc*OAc/NAc)/math.max(1,GAc),lane=BAc.Name})
end
IAc=IAc+MAc
end
if DAc[#DAc]then
table.insert(bb.samples,{pos=DAc[#DAc],prog=1,lane=BAc.Name})
end
end
end
pcall(bb.readHidden,AAc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local QAc=tonumber(bb.ld and bb.ld._portal_lanes)
local RAc=gb.laneList(bb.samples)
if QAc and QAc>=1 and RAc and#RAc>QAc then
bb.laneWant=QAc
end
bb.laneTotal=RAc and#RAc or 1
bb.countLanes()
end
function bb.readHidden(SAc)
local TAc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(TAc)~=CJe[2252]or not next(TAc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local UAc
for VAc,WAc in pairs(SAc)do
if TAc[VAc.Name]and type(WAc.points)==CJe[2252]and#WAc.points>=2 then
local XAc={}
for YAc,ZAc in ipairs(WAc.points)do
XAc[YAc]=U.flat(ZAc.part.Position)
end
local _Ac={}
for aBc,bBc in ipairs(bb.samples)do
local cBc=tostring(bBc.lane)
_Ac[cBc]=_Ac[cBc]or{}
table.insert(_Ac[cBc],bBc)
end
local dBc,eBc
for fBc,gBc in pairs(_Ac)do
local hBc=0
for iBc=1,#XAc,math.max(1,math.floor(#XAc/20))do
local jBc=math.huge
for kBc,lBc in ipairs(gBc)do
local mBc=(U.flat(lBc.pos)-XAc[iBc]).Magnitude
if mBc<jBc then
jBc=mBc
end
end
hBc=hBc+jBc
end
if not eBc or hBc<eBc then
dBc,eBc=fBc,hBc
end
end
local nBc,oBc,pBc,qBc,rBc,sBc={},nil,nil,nil,0,0
for tBc,uBc in ipairs(XAc)do
local vBc,wBc=nil,math.huge
for xBc,yBc in ipairs(_Ac[dBc])do
local zBc=(U.flat(yBc.pos)-uBc).Magnitude
if zBc<wBc then
wBc,vBc=zBc,yBc.prog
end
end
sBc=math.max(sBc,wBc)
if pBc then
local ABc=vBc-pBc
local BBc=(ABc>0.002 and 1)or(ABc< -0.002 and-1)or qBc
if qBc and BBc and BBc~=qBc then
table.insert(nBc,math.floor(pBc*1000+0.5)/1000)
end
qBc,rBc=BBc or qBc,rBc+math.abs(ABc)
else
oBc=vBc
end
pBc=vBc
if tBc%50==0 then
task.wait()
end
end
if pBc and sBc<=8 then
table.insert(nBc,math.floor(pBc*1000+0.5)/1000)
UAc=UAc or{}
UAc[VAc.Name]={from=math.floor((oBc or 0)*1000+0.5)/1000,len=math.floor(rBc*1000+0.5)/1000,turns=nBc,road=dBc}
end
end
end
if not UAc then
return
end
local CBc=bb.ld.map
P.maps[CBc]=P.maps[CBc]or{}
local DBc=P.maps[CBc].hidden
P.maps[CBc].hidden=UAc
if type(DBc)~=CJe[2252]then
for EBc,FBc in pairs(UAc)do
F.log(1,CJe[2938],string.format(CJe[4476],EBc,FBc.len,tostring(FBc.road),math.floor((#FBc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local GBc,HBc,IBc={},0,0
for JBc,KBc in ipairs(bb.samples)do
local LBc=tostring(KBc.lane)
if not GBc[LBc]then
HBc=HBc+1
end
GBc[LBc]=(GBc[LBc]or 0)+1
