local OFc={}
for PFc,QFc in ipairs(bb.samples)do
local RFc=U.flat(QFc.pos)
for SFc,TFc in ipairs(BFc)do
if(RFc-TFc.p).Magnitude<=TFc.r then
local UFc=tostring(QFc.lane)
OFc[UFc]=(OFc[UFc]or 0)+1
if QFc.prog>(MFc[UFc]or 0)then
MFc[UFc]=QFc.prog
end
break
end
end
end
local VFc,WFc={},0
for XFc,YFc in pairs(NFc.by)do
VFc[XFc]=(OFc[XFc]or 0)/math.max(1,YFc)
WFc=math.max(WFc,VFc[XFc])
end
bb.laneW={}
for ZFc,_Fc in pairs(NFc.by)do
bb.laneW[ZFc]=(NFc.avg/math.max(1,_Fc))*(1+1.5*(WFc>0 and(1-VFc[ZFc]/WFc)or 0))
end
bb.laneFrac=VFc
else
bb.laneW,bb.laneFrac=nil,nil
end
