if#BFc>0 then
for dGc,eGc in ipairs(AFc)do
local fGc=(bb.laneW and eGc.lane)and(MFc[tostring(eGc.lane)]or 0)or FFc
if eGc.hp>0 and eGc.prog>fGc+0.02 and eGc.prog>(aGc or 0)then
aGc,cGc=eGc.prog,bb.laneW and eGc.lane or nil
