if eGc.hp>0 and eGc.fly and eGc.prog>GFc+0.02 then
bGc=true
end
end
end
local gGc= #BFc>0 and(bb.pressure or 0)>=FFc-0.08
return{covEnd=FFc,airEnd=GFc,leak=aGc,leakLane=cGc,covL=MFc,airLeak=bGc,push=gGc,units= #BFc}
end
