local xhd=bb.grifNow or bb.grifScan()
if not xhd then
return nil
end
local yhd=xhd.r*bb.GRIF_ROOM
local zhd={}
for Ahd,Bhd in ipairs(bb.cands or{})do
if(U.flat(Bhd)-xhd.p).Magnitude<=yhd then
table.insert(zhd,Bhd)
end
end
for Chd,Dhd in ipairs({0.25,0.45,0.65,0.85})do
for Ehd=0,11 do
local Fhd=Ehd*math.pi/6+Dhd
table.insert(zhd,Vector3 .new(xhd.p.X+math.cos(Fhd)*xhd.r*Dhd,xhd.y,xhd.p.Z+math.sin(Fhd)*xhd.r*Dhd))
end
end
local Ghd,Hhd
for Ihd,Jhd in ipairs(zhd)do
if Ihd%40==0 then
task.wait()
end
local Khd=bb.valid(Jhd,whd)
local Lhd=Khd and(U.flat(Khd)-xhd.p).Magnitude
if Lhd and Lhd<=yhd and(not Hhd or Lhd<Hhd)then
Ghd,Hhd=Khd,Lhd
end
end
return Ghd,Ghd and bb.cover(Ghd,(tonumber(whd.range)or 0))or 0
end
local Mhd=bb.grifS
local Nhd=V.rows(vhd.id)
local Ohd=(Nhd and Nhd[0]and tonumber(Nhd[0].range))or tonumber(whd.range)or 20
local Phd={}
for Qhd,Rhd in ipairs(bb.mine or{})do
if not V.sacFodder(Rhd._stats.id.Value)then
table.insert(Phd,U.flat(Rhd:GetPivot().Position))
end
end
for Shd,Thd in pairs(bb.layout or{})do
if Shd~=vhd.id and not V.sacFodder(Shd)and type(Thd)==CJe[2252]then
for Uhd,Vhd in ipairs(Thd)do
if typeof(Vhd)==CJe[4838]then
table.insert(Phd,U.flat(Vhd))
end
end
end
end
local Whd={}
for Xhd,Yhd in ipairs(bb.cands or{})do
if Xhd%40==0 then
task.wait()
end
local Zhd=bb.valid(Yhd,whd)
if Zhd then
table.insert(Whd,{f=U.flat(Zhd),p=Zhd})
end
end
local _hd,aid
local cid=math.max(1,math.floor(#Whd/150))
for did=1,#Whd,cid do
local eid=Whd[did].f
local fid=true
for gid,hid in ipairs(Phd)do
if(hid-eid).Magnitude<=Ohd+2 then
fid=false
break
end
end
if fid then
local iid=0
for jid,kid in ipairs(Whd)do
if(kid.f-eid).Magnitude<=Ohd*bb.GRIF_ROOM then
iid=iid+1
end
end
if not aid or iid>aid then
_hd,aid=Whd[did],iid
end
end
if did%(cid*10)==0 then
task.wait()
end
end
if not _hd or aid<4 then
if Mhd and not Mhd.off then
Mhd.off,Mhd.offWhy=true,CJe[4839]
F.log(1,CJe[4832],CJe[4840])
end
return nil
end
F.log(2,CJe[4832],string.format(CJe[4841],bb.spotKey(_hd.p),aid))
return _hd.p,0
end
function bb.grifOpts(lid,nid,oid,qid,rid)
local sid=bb.grifS
if not(bb.grifOn()and sid and not sid.done and not sid.off)then
return
end
local tid=bb.grifNow
if not tid or tid.m~=sid.m then
return
end
local vid={}
for wid,xid in ipairs(tid.fodder)do
vid[xid]=true
end
for yid= #lid,1,-1 do
if lid[yid].m and vid[lid[yid].m]then
table.remove(lid,yid)
end
end
sid.more=false
if not bb.grifLong()then
if not sid.lateSaid then
sid.lateSaid=true
F.log(1,CJe[4832],string.format(CJe[4842],bb.GRIF_MIN_WAVES,gb.REINC_LEFT))
end
return
end
local zid=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,zid*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return
end
local Aid=math.max(1,tid.need-tid.yen)
local Bid=(bb.info and tonumber(bb.info.waveSec))or 20
local Cid=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/Bid))
local Did=math.max(0,Aid-nid)/Cid
local Eid=(bb.teamDps or 0)/(1+U.clamp(tonumber(bb.buffLevel())or 0,0,2))/V.GRIF.need/(1+Did/(6*Bid))
if Eid<=0 then
return
end
local Fid=string.format(CJe[4843],U.fmt(tid.yen),U.fmt(tid.need))
for Gid,Hid in ipairs(tid.fodder)do
local Iid=Hid._stats
local Jid=Iid.id.Value
local Kid=V.rows(Jid)
local Lid=tonumber(Iid.upgrade.Value)or 0
local Mid=Kid and Kid[Lid+1]
if Mid and Lid<Kid.max and not((bb.upFail[Hid]or 0)>=3 and U.now()-(bb.upFailAt[Hid]or 0)<60)then
local Nid=1
pcall(function()
Nid=N.USC.calculate_upgrade_cost_multiplier(Hid,N.session())
end)
local Oid=Mid.cost*Nid
sid.more=true
if tid.yen<tid.need then
table.insert(lid,{grif=true,cost=Oid,gain=Eid*Oid,m=Hid,what=string.format(CJe[4844],V.name(Jid),Lid+1,Fid)})
end
end
end
if tid.yen>=tid.need or bb.fieldCount()>=bb.FIELD_MAX or bb.placePaused()then
return
end
for Pid,Qid in ipairs(sid.fodder)do
if#(qid[Qid.uuid]or{})<V.cap(Qid.u)and(bb.noSpot[Qid.uuid]or 0)<3 then
local Rid=(tonumber(Qid.data.cost)or 0)*oid
sid.more=true
table.insert(lid,{place=true,grif=true,cost=Rid,gain=Eid*Rid,e=setmetatable({_grif=true},{__index=Qid}),what=string.format(CJe[4845],V.name(Qid.id),Fid)})
end
end
end
function bb.grifEggGain(Sid,Tid)
local Uid=bb.grifS
if not(bb.grifOn()and Uid and not Uid.done and not Uid.off and bb.grifLong())then
return 0
end
local Vid=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,Vid*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return 0
end
local Wid=(bb.info and tonumber(bb.info.waveSec))or 20
local Xid=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/Wid))
local Yid=math.max(0,V.GRIF.need+(tonumber(Sid)or 0)-(tonumber(Tid)or 0))/Xid
local Zid=(bb.teamDps or 0)/(1+U.clamp(tonumber(bb.buffLevel())or 0,0,2))/V.GRIF.need/(1+Yid/(6*Wid))
