local ljd=U.now()
if not kjd.counted then
if ljd-kjd.at<2 then
return
end
local mjd=0
for njd,ojd in pairs(kjd.units)do
if not(njd.Parent and njd.Parent.Name==CJe[4494])then
mjd=mjd+ojd
end
end
if mjd<=0 then
if ljd-kjd.at>6 then
ijd.cast=nil
end
return
end
kjd.counted=true
ijd.casts=ijd.casts+1
ijd.fed[kjd.m]=(tonumber(ijd.fed[kjd.m])or 0)+mjd
F.log(1,CJe[4832],string.format(CJe[4848],U.fmt(mjd),U.fmt(ijd.fed[kjd.m]),U.fmt(V.GRIF.need),bb.grifAdds()and CJe[1171]or CJe[4849]))
if ijd.fed[kjd.m]<V.GRIF.need then
ijd.cast=nil
end
return
end
if ljd-kjd.at<15 then
return
end
ijd.cast=nil
if not kjd.m.Parent then
return
end
if ijd.casts>=2 and bb.grifAdds()then
P.grif.adds,P.grif.at=false,os.time()
pcall(F.saveSoon)
F.log(1,CJe[4832],string.format(CJe[4850],U.fmt(ijd.fed[kjd.m]),ijd.casts,U.fmt(V.GRIF.need)))
ijd.fed[kjd.m]=0
else
ijd.off,ijd.offWhy,bb.grifZone,bb.grifNow=true,CJe[4851],nil,nil
