local und=mb.board()
F.log(1,CJe[2810],string.format(CJe[4901],nnd and CJe[3035]or CJe[3036],bb.wave(),(tonumber(ond)or 0)/60,mnd,bb.fhMult or 1,tostring(bb.ld.map),tostring(mb.weatherNow()),und and string.format(CJe[4902],und.squares,#und.board)or CJe[1171]))
local vnd={}
