bb.HUNT_WEAK_RUNS=8
bb.HUNT_WEAK_KINDS={CJe[2276],CJe[2273],CJe[2277],CJe[2274],CJe[2278],CJe[2728],CJe[4913],CJe[2272],CJe[2271],CJe[2719]}
function bb.huntWeakText()
local Cnd=type(P.hunt)==CJe[2252]and P.hunt.runs or{}
if#Cnd<bb.HUNT_WEAK_RUNS then
return nil
end
local Dnd,End,Fnd=0,0,{}
for Gnd=1,bb.HUNT_WEAK_RUNS do
local Hnd=Cnd[Gnd]
if type(Hnd)~=CJe[2252]or Hnd.won then
return nil
end
Dnd,End=Dnd+(tonumber(Hnd.pearls)or 0),End+(tonumber(Hnd.sec)or 0)
table.insert(Fnd,tonumber(Hnd.wave)or 0)
end
if End<=0 then
return nil
end
table.sort(Fnd)
local Ind=Fnd[math.ceil(#Fnd/2)]
local Jnd=Dnd/End*60*(tonumber(O.pearlValue)or 0.35)
local Knd={string.format(CJe[4914],bb.HUNT_WEAK_RUNS,Ind,Jnd)}
local Lnd
for Mnd,Nnd in ipairs(W.lastScored or{})do
if Nnd.kind~=CJe[2275]and(tonumber(Nnd.score)or 0)>0 then
Lnd=Nnd
break
end
end
if Lnd then
table.insert(Knd,string.format(CJe[4915],tostring(Lnd.label),Lnd.score))
end
local Ond=0
for Pnd,Qnd in ipairs(bb.HUNT_WEAK_KINDS)do
if O[Qnd]==false then
Ond=Ond+1
end
end
if W.onlyOn()then
table.insert(Knd,CJe[4916])
elseif Ond>=4 then
table.insert(Knd,string.format(CJe[4917],Ond))
end
table.insert(Knd,CJe[4918])
return table.concat(Knd,CJe[2643]),Jnd,Ind
end
function bb.huntWeakNote()
local Rnd=bb.huntWeakText()
if not Rnd then
return
end
F.log(1,CJe[2810],Rnd)
if os.time()-(tonumber(P.hunt.weakSaid)or 0)<6*3600 then
return
end
P.hunt.weakSaid=os.time()
F.saveSoon()
task.delay(8,function()
nb.notify(CJe[2762],Rnd,CJe[3455],15)
end)
end
function bb.pickRogue()
local Snd=bb.rogueOptions
if Snd and bb.hunt then
return bb.huntPick(Snd)
end
if not Snd then
local Tnd=F.request(CJe[4893],CJe[3972],1)
return Tnd
end
bb.fhP=bb.fhP or 1
local Und=tonumber(P.fh.pmin)or 1
local Vnd=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local Wnd,Xnd,Ynd
for Znd,_nd in pairs(Snd)do
local aod,bod=1,0
for cod,dod in pairs(type(_nd)==CJe[2252]and _nd.effects or{})do
if type(dod)==CJe[2252]then
local eod,fod=bb.rogueEffect(dod)
aod=aod*eod
bod=bod+fod
end
end
local god=math.log(math.max(0.05,aod))*10
if bod>0 and bb.fhP*aod>=Und and not Vnd then
god=god+100*bod
elseif bod>0 then
god=god-50+bod
end
if not Xnd or god>Xnd then
Wnd,Xnd,Ynd=Znd,god,aod
end
end
bb.fhP=bb.fhP*(Ynd or 1)
local hod={}
for iod,jod in pairs(Snd)do
local kod={}
for lod,nod in pairs(type(jod)==CJe[2252]and jod.effects or{})do
if type(nod)==CJe[2252]then
table.insert(kod,bb.effectText(nod))
end
end
table.insert(hod,tostring(iod)..CJe[4919]..table.concat(kod,CJe[2902]))
end
bb.rogueOptions=nil
local ood=F.request(CJe[4893],CJe[3972],Wnd)
F.log(1,CJe[4894],string.format(CJe[4920],bb.wave(),tostring(Wnd),Xnd or 0,bb.fhP,Und,table.concat(hod,CJe[4153])))
return ood
end
function bb.rogueShare(pod)
if not pod then
return 0.5
end
local qod=tostring(pod):gsub(CJe[4180],CJe[1171])
local rod,sod=0,0
for tod,uod in ipairs(bb.mine or{})do
local vod=uod._stats.id.Value
if not V.isFarm(vod)then
local wod,xod=pcall(bb.liveDps,uod,vod)
xod=wod and xod or 0
local yod=V.types(vod)
rod=rod+xod
if yod[qod]or yod[qod..CJe[2471]]then
sod=sod+xod
end
end
end
local zod=0
for Aod,Bod in ipairs(bb.mine or{})do
if not V.isFarm(Bod._stats.id.Value)then
zod=zod+1
end
end
local Cod=zod/(zod+4)
return Cod*(rod>0 and sod/rod or 0.5)+(1-Cod)*0.5
end
function bb.resistOf(Dod)
local Eod=V.types(Dod)
local Fod=0
for God,Hod in pairs(bb.fhResist or{})do
local Iod=tostring(God):gsub(CJe[4180],CJe[1171])
if Eod[Iod]or Eod[Iod..CJe[2471]]then
Fod=math.max(Fod,Hod/100)
end
end
return math.min(0.95,Fod)
end
function bb.rogueEffect(Jod)
local Kod,Lod,Mod=Jod.type,tonumber(Jod.amount)or 0,tostring(Jod.stat or CJe[1171])
if Kod==CJe[2812]then
return 1,math.abs(Lod)
end
if Kod==CJe[4304]or Kod==CJe[4309]or Kod==CJe[4305]then
if Mod==CJe[2702]then
return math.max(0.3,1+Lod),0
end
if Mod==CJe[2520]then
return math.max(0.5,1+Lod/2),0
end
if Mod:find(CJe[3059])then
return 1/math.max(0.3,1+Lod),0
end
return 1,0
end
if Kod==CJe[4921]then
if Mod==CJe[2702]then
return math.max(0.3,Lod),0
end
if Mod==CJe[2520]then
return math.max(0.5,1+(Lod-1)/2),0
end
if Mod:find(CJe[3059])then
return 1/math.max(0.3,Lod),0
end
return 1,0
end
if Kod==CJe[4311]then
return 1+Lod/3,0
end
if Kod==CJe[4317]then
return 1/math.max(0.3,1+Lod),0
end
if Kod==CJe[4922]then
return math.max(0.2,1-bb.rogueShare(Jod.damage_type)*(1-100/(100+Lod))),0
end
if Kod==CJe[4923]then
return 1+bb.rogueShare(Jod.damage_type)*Lod,0
end
if Kod==CJe[4924]then
return math.max(0.5,1-Lod*0.5),0
end
if Kod==CJe[4925]then
return math.max(0.5,1-Lod*0.2),0
end
if Kod==CJe[4926]then
return 1+Lod*0.1,0
end
if Kod==CJe[4927]then
return 1/math.max(0.3,1+Lod*0.5),0
end
if Kod==CJe[4928]then
return math.max(0.5,1-Lod*0.1),0
end
if Kod==CJe[4312]then
return 1/math.max(0.3,1+Lod),0
end
if Kod==CJe[4318]then
return math.max(0.3,1-Lod*20),0
end
if Kod==CJe[4319]then
return math.max(0.5,1-Lod*0.03),0
end
if Kod==CJe[4929]then
return 0.95,0
end
if Kod==CJe[4320]then
return math.max(0.5,1-Lod),0
end
if Kod==CJe[4930]then
return 1+math.min(0.3,Lod/40000),0
end
if Kod==CJe[4313]then
return 1/math.max(0.3,1+Lod/2),0
end
if Kod==CJe[4931]then
return 0.8,0
end
if Kod==CJe[4932]then
local Nod=math.max(1,math.abs(Lod))*math.max(1,math.abs(tonumber(Jod.tier)or 1))
return Jod._type==CJe[4933]and 1.1^Nod or 0.8^Nod,0
end
return 1,0
end
function bb.effectText(Ood)
return string.format(CJe[4934],tostring(Ood.type),Ood.stat and(CJe[2852]..tostring(Ood.stat))or CJe[1171],tostring(Ood.amount))
end
function bb.learn()
local Pod=bb.calRun and bb.calRun.potBy
if type(Pod)~=CJe[2252]then
return
end
pcall(bb.sampleHelpers,true)
local Qod={}
for Rod,Sod in pairs(bb.ownDealt or{})do
if not V.isFarm(Sod.id)then
Qod[Sod.id]=(Qod[Sod.id]or 0)+(tonumber(Sod.v)or 0)
end
end
for Tod,Uod in pairs(bb.helperDealt or{})do
if Uod.owner and V.SUMMONER[Uod.owner]and not V.droneHelper(Uod)then
Qod[Uod.owner]=(Qod[Uod.owner]or 0)+(tonumber(Uod.v)or 0)
end
end
local Vod=type(bb.calRun.potExp)==CJe[2252]and bb.calRun.potExp or{}
local Wod,Xod=0,0
local Yod={}
for Zod,_od in pairs(Pod)do
if _od>0 then
Wod,Xod=Wod+(Qod[Zod]or 0),Xod+_od
local apd=tonumber(Vod[Zod])or _od
if apd>0 then
table.insert(Yod,{id=Zod,r=(Qod[Zod]or 0)/apd,w=apd})
end
end
end
if Wod<=0 or Xod<=0 then
return
end
table.sort(Yod,function(bpd,cpd)
return bpd.r<cpd.r
end)
local function dpd(epd)
local fpd,gpd=0,0
for hpd,ipd in ipairs(Yod)do
if ipd.id~=epd then
fpd=fpd+ipd.w
end
end
if fpd<=0 then
return nil
end
for jpd,kpd in ipairs(Yod)do
if kpd.id~=epd then
gpd=gpd+kpd.w
if gpd>=fpd/2 then
return kpd.r
end
end
end
end
bb.lastEff={}
for lpd,mpd in pairs(Pod)do
local npd=dpd(lpd)
if mpd>0 and mpd/Xod>0.02 and npd and npd>0 then
local opd=P.learn[lpd]or{eff=1,n=0,v=6}
V.learnUp(lpd,opd)
local ppd=math.max(0.02,0.25*math.sqrt(30/(30+opd.n)))
local qpd=U.clamp(((Qod[lpd]or 0)/mpd)/npd,0.2,6)
bb.lastEff[lpd]=math.floor(qpd*1000+0.5)/1000
opd.eff=opd.eff+(qpd-opd.eff)*ppd
opd.n=opd.n+1
P.learn[lpd]=opd
end
end
local rpd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if rpd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==CJe[2252]and P.mapLearn or{}
local spd=type(P.mapLearn[rpd])==CJe[2252]and P.mapLearn[rpd]or{}
for tpd,upd in pairs(bb.lastEff)do
local vpd=type(spd[tpd])==CJe[2252]and spd[tpd]or{eff=upd,n=0,v=6}
if(tonumber(vpd.v)or 0)<4 then
vpd.eff,vpd.v=(tonumber(vpd.eff)or upd)*V.secRescale(tpd),4
end
if(tonumber(vpd.v)or 0)<5 then
vpd.eff,vpd.v=(tonumber(vpd.eff)or upd)*(V.sumRescale(tpd)or 1),5
end
if(tonumber(vpd.v)or 0)<6 then
vpd.eff,vpd.v=(tonumber(vpd.eff)or upd)*(1-(V.SUMMONER[tpd]and V.SUMMONER[tpd].droneShare or 0)),6
end
local wpd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(vpd.n)or 0))))
vpd.eff=(tonumber(vpd.n)or 0)==0 and upd or((tonumber(vpd.eff)or upd)+(upd-(tonumber(vpd.eff)or upd))*wpd)
vpd.n=(tonumber(vpd.n)or 0)+1
spd[tpd]=vpd
end
spd._at=os.time()
P.mapLearn[rpd]=spd
if U.count(P.mapLearn)>80 then
local xpd,ypd
for zpd,Apd in pairs(P.mapLearn)do
if not ypd or(tonumber(Apd._at)or 0)<ypd then
xpd,ypd=zpd,tonumber(Apd._at)or 0
end
end
P.mapLearn[xpd]=nil
end
end
end
function bb.randomTeam()
local Bpd=N.session()
local Cpd=Bpd and Bpd.collection.temporary_units or{}
local Dpd,Epd={},{}
local function Fpd(Gpd,Hpd,Ipd)
local Jpd=Gpd and Cpd[Gpd]
if Jpd and N.Units[Jpd.unit_id]and not Epd[Gpd]then
Epd[Gpd]=true
table.insert(Dpd,{slot=Ipd or 99,uuid=Gpd,u=Jpd,id=Jpd.unit_id,data=N.Units[Jpd.unit_id],hand=Hpd})
end
end
for Kpd,Lpd in pairs(Bpd and Bpd.override_equipped_units or{})do
Fpd(Lpd,true,tonumber(Kpd))
end
for Mpd,Npd in ipairs(bb.mine or{})do
local Opd=Npd._stats
Fpd(Opd:FindFirstChild(CJe[2644])and Opd.uuid.Value,false)
end
table.sort(Dpd,function(Ppd,Qpd)
return Ppd.slot<Qpd.slot
end)
return Dpd
end
function bb.fhSnap()
local Rpd,Spd=nil,nil
pcall(function()
for Tpd,Upd in ipairs(workspace._BASES:GetDescendants())do
if Upd:IsA(CJe[2661])then
Rpd,Spd=Upd.Health,Upd.MaxHealth
break
end
end
end)
local Vpd=Rpd and Spd and Spd>0 and math.floor(Rpd/Spd*100)or-1
local Wpd,Xpd,Ypd=0,{},{}
for Zpd,_pd in ipairs(bb.enemies or{})do
if(_pd.prog or 0)>0.8 then
Wpd=Wpd+1
Xpd[tostring(_pd.m)]=(Xpd[tostring(_pd.m)]or 0)+1
end
Ypd[tostring(_pd.m)]=(Ypd[tostring(_pd.m)]or 0)+1
end
if not next(Xpd)then
Xpd=Ypd
end
local aqd=0
for bqd,cqd in ipairs(bb.mine or{})do
local dqd,eqd=pcall(bb.liveDps,cqd,cqd._stats.id.Value)
if dqd and eqd then
aqd=aqd+eqd
end
end
bb.fhWaves=bb.fhWaves or{}
local fqd=0
for gqd,hqd in ipairs(bb.enemies or{})do
if hqd.fly then
fqd=fqd+1
end
end
table.insert(bb.fhWaves,string.format(CJe[4935],bb.wave(),Vpd,#(bb.enemies or{}),Wpd,U.fmt(aqd),bb.fieldCount(),bb.fhMult or 1,U.fmt(bb.money()),math.floor(bb.airShare()*100+0.5),fqd))
if Vpd>=0 and bb.fhLastPct and Vpd<bb.fhLastPct and not bb.fhLeak then
local iqd={}
for jqd,kqd in pairs(Xpd)do
table.insert(iqd,V.name(jqd)..CJe[4936]..kqd)
end
bb.fhLeak=string.format(CJe[4937],bb.wave(),bb.fhLastPct,Vpd,#iqd>0 and table.concat(iqd,CJe[2376])or CJe[4374])
F.log(1,CJe[2938],CJe[4938]..bb.fhLeak)
end
bb.fhLastPct=Vpd
end
function bb.fhRecord(lqd,mqd)
local nqd,oqd={},0
for pqd,qqd in ipairs(bb.mine or{})do
local rqd=qqd._stats
local sqd=rqd:FindFirstChild(CJe[2646])and tonumber(rqd.total_damage.Value)or 0
local tqd=rqd.id.Value
if sqd>0 then
nqd[tqd]=(nqd[tqd]or 0)+sqd
oqd=oqd+sqd
end
end
local uqd={}
for vqd,wqd in pairs(nqd)do
local xqd=oqd>0 and wqd/oqd or 0
local yqd=P.fh.units[vqd]or{n=0,share=0}
yqd.share=(yqd.share*yqd.n+xqd)/(yqd.n+1)
yqd.n=yqd.n+1
P.fh.units[vqd]=yqd
table.insert(uqd,{id=vqd,share=xqd})
end
table.sort(uqd,function(zqd,Aqd)
return zqd.share>Aqd.share
end)
local Bqd={}
for Cqd=1,math.min(4,#uqd)do
table.insert(Bqd,string.format(CJe[3028],V.name(uqd[Cqd].id),math.floor(uqd[Cqd].share*100+0.5)))
end
pcall(bb.fhSnap)
local Dqd=tonumber(P.fh.pmin)or 1
P.fh.pmin=U.clamp(Dqd*(mqd and 0.9 or 1.1),0.5,2.5)
table.insert(P.fh.runs,1,{at=os.time(),wave=bb.wave(),won=mqd or nil,coins=lqd,top=Bqd,mult=bb.fhMult or 1,discards=bb.discards,strength=bb.fhP,floor=Dqd,effects=bb.fhEffects,picks=bb.fhPicks,leak=bb.fhLeak,waves=bb.fhWaves})
while#P.fh.runs>20 do
table.remove(P.fh.runs)
end
F.log(1,CJe[4939],string.format(CJe[4940],bb.wave(),table.concat(Bqd,CJe[2376])))
end
function bb.carry(Eqd)
