end
local Sqd=0
for Tqd in pairs(P.unitData)do
Sqd=Sqd+1
end
local Uqd=0
for Vqd,Wqd in ipairs(Gqd)do
if Wqd.won then
Uqd=Uqd+1
end
end
local Xqd=Gqd[1]
local Yqd,Zqd=P.fh.merge,P.fh.idol
local _qd=CJe[1171]
if Yqd and Yqd.n>0 then
