end
return string.format(CJe[4948]..CJe[4949]..CJe[4950],#Gqd,Uqd,Hqd/ #Gqd,math.floor(Iqd/ #Gqd+0.5),tostring(Xqd.wave),tonumber(Xqd.mult)or 1,tonumber(Xqd.strength)or 1,Xqd.leak and(CJe[4951]..Xqd.leak)or CJe[1171],table.concat(Xqd.top or{},CJe[2376]),tonumber(P.fh.pmin)or 1,#Qqd>0 and table.concat(Qqd,CJe[2643])or CJe[4952],Sqd,_qd)
end
function bb.cardDps(drd)
local erd,frd=pcall(V.dps,drd.u,0,bb.mod)
frd=erd and tonumber(frd)or 0
if frd>0 or V.isFarm(drd.id)or V.idol(drd.id)or V.allyBuff(drd.id)then
return frd
end
local grd=table.clone(bb.cardVals or{})
if#grd==0 then
return 1000
end
table.sort(grd)
return grd[math.max(1,math.ceil(#grd*0.6))]
end
function bb.cardValue(hrd)
if V.isFarm(hrd.id)then
return 0
end
if V.idol(hrd.id)then
return(bb.teamDps or 0)*bb.idolStep()*3
end
local ird=V.allyBuff(hrd.id)and bb.buffGain(hrd)or bb.cardDps(hrd)
return ird*(1+2*bb.carry(hrd.id))*(1-bb.resistOf(hrd.id))*bb.airNeed(hrd.id)*(bb.mergeIds[hrd.id]and 2 or 1)
end
function bb.flyMode()
if bb.random or bb.flyerSeen then
