bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(Evd,Fvd)
local Gvd=(Fvd.t or 0)-(Evd.t or 0)
if Gvd<bb.BASE_WIN-1 then
return false
end
local Hvd=((tonumber(Evd.base)or 0)-(tonumber(Fvd.base)or 0))/Gvd
if Hvd<=0 or(tonumber(Fvd.base)or 0)<=0 then
return false
end
local Ivd=Fvd.base/Hvd
local Jvd,Kvd=0,0
local Lvd,Mvd=Evd.foes or{},Fvd.foes or{}
for Nvd,Ovd in pairs(Mvd)do
if Ovd.prog>=bb.BASE_END then
Jvd=Jvd+Ovd.hp
local Pvd=Lvd[Nvd]
if Pvd then
Kvd=Kvd+math.max(0,Pvd.hp-Ovd.hp)
end
end
end
for Qvd,Rvd in pairs(Lvd)do
if Rvd.prog>=bb.BASE_END and not Mvd[Qvd]then
Kvd=Kvd+Rvd.hp
end
end
if Jvd<=0 then
return false
end
local Svd=Kvd/Gvd
local Tvd=Svd>0 and Jvd/Svd or math.huge
local Uvd={baseTime=Ivd,loss=Hvd,atEnd=Jvd,rate=Svd,killTime=Tvd}
return Ivd<bb.BASE_SOON and Tvd>Ivd*bb.BASE_MARGIN,Uvd
end
