table.insert(fAd,{tg=mAd,tp=U.flat(sAd.Position),at=U.flat(iAd:GetPivot().Position),r=tonumber(jAd.range.Value)or 0,fam=pAd.holdFam,air=pAd.ccAir,need=2*(tAd>0 and tAd or 2),full=pAd.full,blast=math.min(12,math.max(0,((tonumber(pAd.n)or 1)-1)*5))})
