local pBd=(tonumber(lBd.data and lBd.data.cost)or 0)*jBd
local qBd,rBd
for sBd,tBd in ipairs(mBd)do
local uBd=tBd._stats
local vBd,wBd=U.flat(tBd:GetPivot().Position),uBd.range.Value
local xBd=false
for yBd,zBd in ipairs(bb.samples)do
