if type(YEe)==CJe[2252]and type(YEe.uuids)==CJe[2252]and type(YEe.names)==CJe[2252]and#YEe.names== #(XEe.team or{})then
local ZEe={}
for _Ee,aFe in ipairs(YEe.names)do
ZEe[aFe]=(ZEe[aFe]or 0)+1
end
local bFe=true
for cFe,dFe in ipairs(XEe.team or{})do
if not ZEe[dFe]or ZEe[dFe]<=0 then
bFe=false
else
ZEe[dFe]=ZEe[dFe]-1
end
end
if bFe then
return YEe.uuids
end
end
local eFe=N.session()
if not eFe then
return nil
end
local fFe={}
for gFe,hFe in ipairs(V.equipped())do
fFe[hFe.uuid]=true
end
local iFe,jFe={},{}
for kFe,lFe in ipairs(XEe.ids or{})do
local mFe,nFe
for oFe,pFe in pairs(eFe.profile_data.collection.owned_units)do
if pFe.unit_id==lFe and not jFe[oFe]then
local qFe=(fFe[oFe]and 1e12 or 0)+(tonumber(pFe.xp)or 0)
if not nFe or qFe>nFe then
mFe,nFe=oFe,qFe
end
end
end
if not mFe then
return nil
end
jFe[mFe]=true
table.insert(iFe,mFe)
end
return#iFe>0 and iFe or nil
end
